# How to step through a String in a multibyte encoding. `zr-dev gen
# enc_mb` generates this from the Onigmo encoders that Regexp uses. Each
# encoding's descriptor (Regexp::Onig::Enc::Base#descriptor) contains the
# lead-byte lengths and state tables of its enc/*.c file. The matcher's
# zr_onig_precise_len also reads them, so a String and a Regexp on it
# find the same characters.

module Zr::Kern
  # Whether the encoding `index` has multibyte characters of its own
  # kind: not UTF-8, not UTF-16 or UTF-32, and not one byte for each
  # character.
  sig [Word] => Bool
  def zr_enc_mb_p(index)
    index >= 10 && index <= 21 || index == 39 || index >= 76 && index <= 77 || index >= 79 && index <= 84 || index == 93 || index == 96 || index == 98 || index == 100 || index == 102
  end

  # Whether the encoding writes its characters in the same way as UTF-8.
  sig [Word] => Bool
  def zr_enc_utf8_like_p(index)
    index == 9 || index == 95 || index == 97 || index == 101
  end

  # The descriptor to step through a multibyte encoding, or 0 for other
  # encodings.
  sig [Word] => Word
  def zr_enc_mb_descriptor(index)
    # EUC-JP, eucJP-ms, CP51932, EUC-JIS-2004
    if index == 10 || index >= 80 && index <= 82
      return Machine.word(zr_enc_mb_euc_jp)
    end
    # Windows-31J, SJIS-DoCoMo, SJIS-KDDI, SJIS-SoftBank, Shift_JIS, MacJapanese
    if index == 11 || index == 39 || index == 93 || index == 96 || index == 98 || index == 102
      return Machine.word(zr_enc_mb_windows_31j)
    end
    # Big5, Big5-HKSCS, Big5-UAO, CP950, CP951
    if index >= 12 && index <= 14 || index >= 76 && index <= 77
      return Machine.word(zr_enc_mb_big5)
    end
    # CESU-8
    if index == 15
      return Machine.word(zr_enc_mb_cesu_8)
    end
    # CP949
    if index == 16
      return Machine.word(zr_enc_mb_cp949)
    end
    # Emacs-Mule, stateless-ISO-2022-JP, stateless-ISO-2022-JP-KDDI
    if index == 17 || index == 79 || index == 100
      return Machine.word(zr_enc_mb_emacs_mule)
    end
    # EUC-KR, GB2312, GB12345
    if index == 18 || index >= 83 && index <= 84
      return Machine.word(zr_enc_mb_euc_kr)
    end
    # EUC-TW
    if index == 19
      return Machine.word(zr_enc_mb_euc_tw)
    end
    # GB18030
    if index == 20
      return Machine.word(zr_enc_mb_gb18030)
    end
    # GBK
    if index == 21
      return Machine.word(zr_enc_mb_gbk)
    end
    0
  end

